// Package storagea mirrors the CURRENT nsdata record shape, field for
// field, so its on-chain size can be compared against the slim variant
// in storageb. Nothing here is meant to ship.
package storagea

import (
	"time"

	"gno.land/p/nt/avl/v0"
)

type Rec struct {
	label      string // duplicated: the tree key already holds this
	owner      address
	registered time.Time // {sec int64, nsec int32, loc *Location}
	expires    time.Time
	streak     int64
	frozen     bool
	isNFT      bool
	extra      avl.Tree // allocated even when empty
}

var recs avl.Tree

// Add inserts one record under the given key. Called repeatedly to grow
// the tree, since AVL insert cost varies with tree size.
func Add(cur realm, key string) {
	now := time.Now()
	recs.Set(key, &Rec{
		label:      key,
		owner:      cur.Previous().Address(),
		registered: now,
		expires:    now.Add(365 * 24 * time.Hour),
		streak:     0,
		frozen:     false,
		isNFT:      true,
		extra:      avl.Tree{},
	})
}

func Count() int { return recs.Size() }

// Package storageb is the SLIM candidate record shape, to be compared
// against storagea. Four changes, each of which should be free of any
// functional cost:
//
//  1. no `label` -- the tree key already is the label, so storing it
//     again is pure duplication (verified: nsdata never reads it)
//  2. int64 unix seconds instead of time.Time -- Time carries an unused
//     nanosecond field and a *Location pointer for values that are
//     always UTC, twice per record
//  3. streak and the booleans packed into one int64
//  4. *avl.Tree instead of avl.Tree -- nil until an extension key is
//     actually written, rather than allocated for every record
package storageb

import (
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	flagFrozen  = int64(1) << 0
	flagIsNFT   = int64(1) << 1
	streakShift = 8
)

type Rec struct {
	owner      address
	registered int64 // unix seconds
	expires    int64
	flags      int64 // streak << 8 | bools
	extra      *avl.Tree
}

func (r *Rec) Streak() int64 { return r.flags >> streakShift }
func (r *Rec) Frozen() bool  { return r.flags&flagFrozen != 0 }
func (r *Rec) IsNFT() bool   { return r.flags&flagIsNFT != 0 }

var recs avl.Tree

func Add(cur realm, key string) {
	now := time.Now().Unix()
	recs.Set(key, &Rec{
		owner:      cur.Previous().Address(),
		registered: now,
		expires:    now + 365*24*3600,
		flags:      flagIsNFT,
	})
}

func Count() int { return recs.Size() }

package main

import (
	"gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/storagea"
	"gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/storageb"
)

// Same keys, same order, into both trees — so any difference in storage
// is the record shape and nothing else.
func main(cur realm) {
	keys := []string{"degen", "ngmi", "lambo", "anon", "cope", "hodl", "moon", "frog"}
	for _, k := range keys {
		storagea.Add(cross(cur), k)
		storageb.Add(cross(cur), k)
	}
	println("added", len(keys), "to each")
}

// Package storagec isolates ONE change from the slim variant: int64
// unix seconds instead of time.Time. Everything else matches storagea
// exactly -- the duplicated label stays, the booleans stay separate,
// the extension tree is still allocated by value.
//
// storageb changed four things at once and saved ~1,615 bytes. This
// says how much of that was the timestamps alone, which decides whether
// the other three are worth making at all.
package storagec

import (
	"time"

	"gno.land/p/nt/avl/v0"
)

type Rec struct {
	label      string   // kept, same as storagea
	owner      address
	registered int64    // CHANGED: was time.Time
	expires    int64    // CHANGED: was time.Time
	streak     int64
	frozen     bool     // kept separate
	isNFT      bool     // kept separate
	extra      avl.Tree // kept by value
}

var recs avl.Tree

func Add(cur realm, key string) {
	now := time.Now().Unix()
	recs.Set(key, &Rec{
		label:      key,
		owner:      cur.Previous().Address(),
		registered: now,
		expires:    now + 365*24*3600,
		streak:     0,
		frozen:     false,
		isNFT:      true,
		extra:      avl.Tree{},
	})
}

func Count() int { return recs.Size() }

