	"gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/storagec"
)

// Same nine keys, same order, as the other two realms.
func main(cur realm) {
	keys := []string{"wagmi", "degen", "ngmi", "lambo", "anon", "cope", "hodl", "moon", "frog"}
	for _, k := range keys {
		storagec.Add(cross(cur), k)
	}
	println("added", len(keys))
}

