// Package storaged is storagea PLUS a GRC-721 mint per record, so the
// cost of minting a token can be separated from the cost of the record
// that owns it. Everything else is identical to storagea field for
// field, so the difference between the two is the mint and nothing else.
//
// The question it answers: nsdata already supports registering a name
// with mintNFT=false and promoting it later via PromoteToNFTRecord. If
// the token is a large share of the per-name cost, deferring it is a
// real saving on every registration that never gets promoted.
package storaged

import (
	"time"

	"gno.land/p/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/grc721"
	"gno.land/p/nt/avl/v0"
)

type Rec struct {
	label      string
	owner      address
	registered time.Time
	expires    time.Time
	streak     int64
	frozen     bool
	isNFT      bool
	extra      avl.Tree
}

var (
	recs avl.Tree
	nft  *grc721.BasicNFT
)

func init(cur realm) {
	nft = grc721.NewBasicNFT(0, cur, "Storage Test", "ST")
}

func Add(cur realm, key string) {
	now := time.Now()
	owner := cur.Previous().Address()
	recs.Set(key, &Rec{
		label:      key,
		owner:      owner,
		registered: now,
		expires:    now.Add(365 * 24 * time.Hour),
		streak:     0,
		frozen:     false,
		isNFT:      true,
		extra:      avl.Tree{},
	})
	// the one difference from storagea
	if err := nft.Mint(owner, grc721.TokenID(key)); err != nil {
		panic(err)
	}
}

func Count() int { return recs.Size() }

package main

import (
	"gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/storaged"
)

// Same nine keys, same order, as storagea — so the only variable left
// between the two realms is the GRC-721 mint.
func main(cur realm) {
	keys := []string{"wagmi", "degen", "ngmi", "lambo", "anon", "cope", "hodl", "moon", "frog"}
	for _, k := range keys {
		storaged.Add(cross(cur), k)
	}
	println("added", len(keys))
}

// Package storagee measures the cheapest useful thing this project could
// store: one small entry in a tree, keyed by a composite string.
//
// That is the shape of BOTH a vote ("proposal:voter" -> when) and a
// grant ("address" -> the name they may claim free). Neither needs a
// struct, a timestamp object or a nested tree, so both should cost far
// less than a name record -- but "should" is not a number, and the point
// of asking what a vote costs is to get a number.
package storagee

import (
	"gno.land/p/nt/avl/v0"
)

var entries avl.Tree

// Set stores one entry. The value is a short string, which is all a vote
// or a grant actually needs.
func Set(cur realm, key, value string) {
	entries.Set(key, value)
}

func Count() int { return entries.Size() }

package main

import (
	"gno.land/r/g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku/storagee"
)

// Twenty entries shaped like real votes: "proposal:voter" -> a short
// timestamp string. Twenty rather than nine so the per-entry figure is
// not dominated by the first few inserts into an empty tree.
func main(cur realm) {
	props := []string{"nft", "moon", "based", "chad"}
	voters := []string{
		"g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme",
		"g1gn6t0q9wenwhdda47rkrpfd63kcxjvyp7eqwku",
		"g1w7kytlgsgstspzlpy4fdtd9uqf0ga2dzud4wzv",
		"g1n27703259g9ts046dqzly6h6ynp2cuf6hfez3c",
		"g1j2adx6ngvawtmkhq7eexsk9uq4u9zsrealpye2",
	}
	n := 0
	for _, p := range props {
		for _, v := range voters {
			storagee.Set(cross(cur), p+":"+v, "1787500000")
			n++
		}
	}
	println("entries:", n)
}
